/** Something that can be done on an area (gardening, beekeeping…), known by its code. */
export interface AreaActivity {
  uuid: string;
  /** Only in lists: the API leaves it out of a single activity. */
  code?: string;
  /** Only on a single activity: the API leaves it out of lists. */
  createdAt?: Date;
}

export interface AreaActivityCreateInput {
  /** Generated by the API when left out. */
  uuid?: string;
  code: string;
}

/** The fields to change; those left out are kept. */
export type AreaActivityUpdateInput = Partial<Omit<AreaActivityCreateInput, 'uuid'>>;
